sc_cat_item_producer.script:
(function() {
    var building = producer.lab_1009;
    var bldg = JSON.parse(building);
    var bldgJson = {};
    var count = 0;
    var shDesc = '';

    for (var b = 0; b < bldg.length; b++) { //loop through ALL of the buildings
        var repData = new GlideRecord('x_hccc_hoc_ohs_lab1058_staging_table');
        repData.addQuery('report_year', producer.ohsm_repo_year);
        repData.addQuery('building', bldg[b].building);
        repData.query();
        repData.next();

        var loc = new GlideRecord('cmn_location');
        loc.get('sys_id', bldg[b].building);

        var address = loc.name + '\n' + loc.street + ',\n' + loc.city + ', ' + loc.state + ' ' + loc.zip;

        var disabling = repData.disabling_injury.split(',');
        var minor = repData.minor_injury.split(',');

        switch (count) {
            case 0:
                bldgJson.year = producer.ohsm_repo_year.toString();
                bldgJson.building1 = bldg[b].building;
                bldgJson.headquarter1 = bldg[b].headquarters;
                bldgJson.deaths1 = bldg[b].number_of_deaths;
                bldgJson.other1 = bldg[b].number_of_other_hazardous_occurrences;
                bldgJson.totEmp1 = bldg[b].total_number_of_employees;
                bldgJson.officeEmp1 = bldg[b].number_of_office_employees;
                bldgJson.hours1 = bldg[b].total_number_of_hours_worked;
                bldgJson.comment1 = bldg[b].comments;
                bldgJson.disabling1 = disabling[12];
                bldgJson.minor1 = minor[12];
                bldgJson.addr1 = address;
                count++;
                break;
            case 1:
                bldgJson.building2 = bldg[b].building;
                bldgJson.headquarter2 = bldg[b].headquarters;
                bldgJson.deaths2 = bldg[b].number_of_deaths;
                bldgJson.other2 = bldg[b].number_of_other_hazardous_occurrences;
                bldgJson.totEmp2 = bldg[b].total_number_of_employees;
                bldgJson.officeEmp2 = bldg[b].number_of_office_employees;
                bldgJson.hours2 = bldg[b].total_number_of_hours_worked;
                bldgJson.comment2 = bldg[b].comments;
                bldgJson.disabling2 = disabling[12];
                bldgJson.minor2 = minor[12];
                bldgJson.addr2 = address;
                count++;
                break;
            case 2:
                bldgJson.building3 = bldg[b].building;
                bldgJson.headquarter3 = bldg[b].headquarters;
                bldgJson.deaths3 = bldg[b].number_of_deaths;
                bldgJson.other3 = bldg[b].number_of_other_hazardous_occurrences;
                bldgJson.totEmp3 = bldg[b].total_number_of_employees;
                bldgJson.officeEmp3 = bldg[b].number_of_office_employees;
                bldgJson.hours3 = bldg[b].total_number_of_hours_worked;
                bldgJson.comment3 = bldg[b].comments;
                bldgJson.disabling3 = disabling[12];
                bldgJson.minor3 = minor[12];
                bldgJson.addr3 = address;
                count++;
                break;
            case 3:
                bldgJson.building4 = bldg[b].building;
                bldgJson.headquarter4 = bldg[b].headquarters;
                bldgJson.deaths4 = bldg[b].number_of_deaths;
                bldgJson.other4 = bldg[b].number_of_other_hazardous_occurrences;
                bldgJson.totEmp4 = bldg[b].total_number_of_employees;
                bldgJson.officeEmp4 = bldg[b].number_of_office_employees;
                bldgJson.hours4 = bldg[b].total_number_of_hours_worked;
                bldgJson.comment4 = bldg[b].comments;
                bldgJson.disabling4 = disabling[12];
                bldgJson.addr4 = address;
                bldgJson.minor4 = minor[12];

                var chld = new GlideRecord('sn_hr_core_task');
                chld.initialize();
                chld.parent = current.sys_id;
                chld.json_draft = JSON.stringify(bldgJson);
                chld.short_description = producer.ohsm_repo_year + ' - ' + 'ESDC LAB 1009';
                chld.hr_service = '31ecd2f31b081d109fde86acdd4bcb9b';
                chld.opened_for = current.opened_for;
                chld.subject_person = current.subject_person;
                chld.pdf_template = current.pdf_template;
                chld.send_report_to = producer.ohsm_repo_sent_reportto;

                chld.insert();

                //reset variables
                count = 0;
                bldgJson = {};
                shDesc = '';

        }

    }

})();
